UPDATE wms_return_order
return_no = #{returnNo}, return_type = #{returnType}, warehouse_id = #{warehouseId}, customer_name = #{customerName}, original_shipment_no = #{originalShipmentNo}, status = #{status}, total_quantity = #{totalQuantity}, actual_quantity = #{actualQuantity}, return_reason = #{returnReason}, receive_time = #{receiveTime}, complete_time = #{completeTime}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
