mapper.select:
SELECT

FROM wms_return_order ro
LEFT JOIN wms_warehouse w ON ro.warehouse_id = w.id

    AND ro.return_type = #{returnType}
    AND ro.status = #{status}
    AND ro.warehouse_id = #{warehouseId}
    AND ro.original_shipment_no LIKE CONCAT('%', #{originalShipmentNo}, '%')

ORDER BY ro.create_time DESC

